-- Italian Kitchen: 21 recipes
insert into "CozyCookBookSchema".folders (id, name, blurb, user_id, is_public, position) values
  ('45a290aa-41d0-5384-90df-089786a69dbe', 'Italian Kitchen', 'Regional Italian cooking with the shortcuts left out — the pasta sauces are emulsions, not cream.', null, true, 1024)
on conflict (id) do update set name = excluded.name, blurb = excluded.blurb;

insert into "CozyCookBookSchema".recipes
  (id, title, ingredients, steps, folder_id, user_id, meal, is_public, position)
select r.id, r.title,
  (select coalesce(jsonb_agg(jsonb_build_object('id', gen_random_uuid(), 'name', n, 'isChecked', false) order by o), '[]'::jsonb)
   from unnest(r.ing) with ordinality as t(n, o)),
  (select coalesce(jsonb_agg(jsonb_build_object('id', gen_random_uuid(), 'text', st, 'isChecked', false) order by o), '[]'::jsonb)
   from unnest(r.steps) with ordinality as t(st, o)),
  '45a290aa-41d0-5384-90df-089786a69dbe', null, r.meal, true, r.pos
from (values
  ('60d9b111-1c85-5380-be49-d32ee6253263'::uuid, 'Cornetto and Cappuccino', array['4 cornetti','2 cups whole milk','4 shots espresso','Granulated sugar to taste'], array['Warm the cornetti briefly so the sugar on top just catches.','Pull four espressos.','Steam the milk to a fine wet paint texture, not stiff foam.','Pour a third milk, two thirds coffee. Standing at the counter is traditional.'], 'Breakfast', 0),
  ('aa188027-ed9c-541b-b15b-6f2aeae20549'::uuid, 'Torta della Nonna', array['2 cups all-purpose flour','1/2 cup granulated sugar','1/2 cup butter, cold','3 large eggs','2 cups whole milk','1 lemon, zested','1/4 cup cornstarch','1/2 cup pine nuts','1 tsp vanilla extract'], array['Make a short pastry with the flour, sugar, cold butter and one egg. Chill it.','Heat the milk with the lemon zest.','Whisk the remaining eggs, sugar and cornstarch, temper in the milk, and cook to a thick custard.','Line a tin with two-thirds of the pastry, fill, lid it, and scatter pine nuts.','Bake at 350°F for 40 minutes and dust with icing sugar.'], 'Breakfast', 1024),
  ('712c93e0-c8b7-59af-9718-3f65a92b1660'::uuid, 'Uova in Purgatorio', array['4 large eggs','1 can crushed tomatoes','3 cloves garlic, sliced','3 tbsp olive oil','1/4 tsp chili flakes','1/4 cup fresh basil','Salt to taste','Crusty bread to serve'], array['Soften the garlic and chili in olive oil without colouring it.','Add the tomatoes and simmer 15 minutes until the sauce is no longer watery.','Make wells and crack in the eggs. Cover and cook until the whites set.','Basil over the top, bread alongside.'], 'Breakfast', 2048),
  ('c13ab72e-2929-5fa9-8f7d-55e7a179344d'::uuid, 'Spaghetti Carbonara', array['1 lb spaghetti','8 oz guanciale, diced','4 large eggs','2 egg yolks','1 1/2 cups Pecorino Romano, grated','2 tsp black pepper','Salt to taste'], array['Render the guanciale slowly until the fat runs and the meat crisps.','Beat the eggs, yolks, cheese and a great deal of black pepper.','Cook the spaghetti and save a mug of the water.','Off the heat — genuinely off — toss the pasta with the fat, then the egg mixture, loosening with pasta water.','No cream. The sauce is egg and starch and nothing else.'], 'Lunch', 3072),
  ('03b1e84a-2e93-565e-9fcf-7354823d4de4'::uuid, 'Cacio e Pepe', array['1 lb tonnarelli or spaghetti','2 cups Pecorino Romano, grated','1 tbsp black pepper, coarsely cracked','Salt to taste'], array['Toast the pepper in a dry pan until it smells of pepper rather than dust.','Cook the pasta in deliberately under-salted, minimal water so it goes starchy.','Make a paste of pecorino and a little cool pasta water — cool, or it clumps.','Toss everything off the heat, adding water until it turns glossy.'], 'Lunch', 4096),
  ('a0d8a2d5-0122-5e44-aa46-bb82958c9b43'::uuid, 'Panzanella', array['4 cups stale bread, torn','4 heirloom tomatoes, chunked','1 cucumber, sliced','1 red onion, sliced thin','1/2 cup fresh basil','1/3 cup olive oil','3 tbsp red wine vinegar','Salt to taste'], array['Salt the tomatoes in a colander for 20 minutes and keep the juice.','Soak the bread in that juice with the vinegar.','Toss everything with the oil and let it sit half an hour.','It should be soft but not mush — stale bread matters.'], 'Lunch', 5120),
  ('8ef6a937-bc82-5c68-93a8-25e8c8bb20eb'::uuid, 'Minestrone', array['2 tbsp olive oil','1 cup mirepoix','2 cloves garlic, minced','1 can cannellini beans','1 can diced tomatoes','1 zucchini, diced','2 cups green beans','6 cups vegetable stock','1 cup small pasta','1/4 cup fresh basil','Parmesan rind'], array['Soften the mirepoix in oil for a full ten minutes.','Add the garlic, tomatoes and stock with the parmesan rind.','Simmer 30 minutes, then add the beans and vegetables.','Cook the pasta in the soup at the end so it releases its starch.'], 'Lunch', 6144),
  ('a589f4b9-0d74-516a-9498-27322d2409b5'::uuid, 'Margherita Pizza', array['500g bread flour','325ml water','10g salt','3g active dry yeast','1 can San Marzano tomatoes','250g fresh mozzarella','1/4 cup fresh basil','3 tbsp olive oil'], array['Mix the dough and rest 20 minutes, then knead briefly and prove 24 hours in the fridge.','Ball the dough and let it come to room temperature for 4 hours.','Crush the tomatoes by hand with salt — do not cook them.','Stretch by hand, never with a rolling pin.','Bake as hot as your oven goes, on a preheated stone, 6-8 minutes.','Basil goes on after the oven, not before.'], 'Lunch', 7168),
  ('d72bebb5-d5f6-573d-943b-35a73fe57988'::uuid, 'Risotto alla Milanese', array['1 1/2 cups arborio rice','1 pinch saffron threads','1 yellow onion, minced','1/2 cup white wine','6 cups chicken stock','4 tbsp butter','1 cup Parmesan, grated','Salt to taste'], array['Steep the saffron in a ladle of warm stock.','Soften the onion in butter; toast the rice until the edges turn translucent.','Deglaze with wine and let it disappear.','Add hot stock a ladle at a time, stirring, for about 18 minutes.','Off the heat, beat in cold butter and parmesan hard. It should ripple on the plate.'], 'Dinner', 8192),
  ('eece3923-d65c-5c01-a0f3-e66f1490098a'::uuid, 'Lasagne alla Bolognese', array['1 lb lasagne sheets','1 lb ground beef','8 oz pancetta, diced','1 cup mirepoix','1 cup whole milk','1 cup red wine','1 can crushed tomatoes','4 tbsp butter','1/4 cup all-purpose flour','4 cups whole milk','2 cups Parmesan, grated','Pinch of nutmeg'], array['Brown the pancetta and beef, then soften the mirepoix in the fat.','Add the milk and cook it away — this is what makes the meat tender.','Add the wine, cook it away, then the tomatoes. Simmer three hours.','Make a béchamel with the butter, flour, milk and nutmeg.','Layer ragù, béchamel, pasta, parmesan, ending with béchamel.','Bake at 375°F for 45 minutes and rest 20 before cutting.'], 'Dinner', 9216),
  ('4c9f061d-f94a-5603-b848-44d2c6903022'::uuid, 'Osso Buco', array['4 veal shanks','1/2 cup all-purpose flour','1 cup mirepoix','1 cup white wine','2 cups chicken stock','1 can diced tomatoes','2 fresh rosemary sprigs','1 lemon, zested','2 cloves garlic, minced','1/4 cup fresh parsley'], array['Tie each shank so it holds together, dredge in flour, and brown deeply.','Soften the mirepoix, deglaze with wine, add stock, tomatoes and herbs.','Braise covered at 325°F for two hours until the meat gives.','Mix the lemon zest, garlic and parsley into a gremolata and scatter it over at the table.'], 'Dinner', 10240),
  ('83e24b5b-91b9-5a03-9646-8a470310c996'::uuid, 'Chicken Piccata', array['4 chicken breasts, pounded thin','1/2 cup all-purpose flour','3 tbsp olive oil','4 tbsp butter','1/2 cup white wine','1/2 cup chicken stock','3 tbsp lemon juice','3 tbsp capers','1/4 cup fresh parsley'], array['Pound the chicken to an even thickness and dredge in seasoned flour.','Sear in oil and butter, 3 minutes a side, then set aside.','Deglaze with wine, add stock, lemon and capers, and reduce by half.','Swirl in cold butter off the heat and return the chicken to coat.'], 'Dinner', 11264),
  ('f7af1d23-5494-553c-bbaf-699d8cf11ce6'::uuid, 'Melanzane alla Parmigiana', array['3 eggplants, sliced','2 cups all-purpose flour','4 large eggs, beaten','Oil for frying','1 can crushed tomatoes','3 cloves garlic, sliced','500g fresh mozzarella','1 1/2 cups Parmesan, grated','1/4 cup fresh basil'], array['Salt the eggplant slices and drain them an hour. This is not optional.','Flour, egg, and shallow-fry until golden. Drain well.','Simmer the tomatoes with garlic and basil for 20 minutes.','Layer eggplant, sauce, both cheeses, and repeat.','Bake at 375°F for 40 minutes and rest 15 minutes.'], 'Dinner', 12288),
  ('824d2f21-8116-5544-a4fa-2311694f98a9'::uuid, 'Cacciatore', array['8 chicken thighs','2 tbsp olive oil','1 red bell pepper, sliced','1 yellow onion, sliced','8 oz cremini mushrooms, sliced','3 cloves garlic, minced','1/2 cup red wine','1 can diced tomatoes','2 fresh rosemary sprigs','Salt to taste','Black pepper to taste'], array['Brown the thighs skin-side down until the skin releases on its own.','Soften the pepper, onion and mushrooms in the rendered fat.','Deglaze with wine, add tomatoes and rosemary, return the chicken.','Simmer uncovered 40 minutes so the sauce tightens around it.'], 'Dinner', 13312),
  ('067f9ae2-5095-56c2-b452-347ebcb976cb'::uuid, 'Linguine alle Vongole', array['1 lb linguine','2 lbs clams, scrubbed','4 cloves garlic, sliced','1/3 cup olive oil','1/2 cup white wine','1/4 tsp chili flakes','1/4 cup fresh parsley','Salt to taste'], array['Purge the clams in salted water for an hour.','Soften the garlic and chili in oil; add the clams and wine and cover.','Pull each clam out the moment it opens so none overcook.','Cook the linguine very al dente and finish it in the clam liquor.','Return the clams, add parsley, and toss hard to emulsify.'], 'Dinner', 14336),
  ('0836bb30-af30-5fb0-9666-08f104b5cec1'::uuid, 'Tiramisu', array['6 egg yolks','3/4 cup granulated sugar','500g mascarpone','1 1/2 cups heavy cream','2 cups strong espresso, cooled','1/4 cup Marsala wine','2 packages ladyfingers','Cocoa powder for dusting'], array['Whisk the yolks and sugar over a bain-marie until thick and pale, then cool.','Fold in the mascarpone, then softly whipped cream.','Combine the espresso and Marsala. Dip each ladyfinger for one second only.','Layer biscuits and cream twice. Chill six hours.','Dust with cocoa immediately before serving, never before.'], 'Snack', 15360),
  ('579fcd2f-d81f-5cd6-a763-ba4f2b86a0d2'::uuid, 'Panna Cotta', array['2 cups heavy cream','1/2 cup whole milk','1/2 cup granulated sugar','1 tsp vanilla extract','2 tsp gelatin','2 tbsp cold water','1 cup berries'], array['Bloom the gelatin in the cold water.','Heat the cream, milk, sugar and vanilla to a bare steam — do not boil.','Stir in the gelatin until dissolved.','Pour into moulds and chill four hours. It should barely hold its shape.','Serve with macerated berries.'], 'Snack', 16384),
  ('9a0df549-4828-5cbe-b483-2a12103e7449'::uuid, 'Cannoli', array['12 cannoli shells','500g ricotta, drained overnight','3/4 cup powdered sugar','1/2 tsp cinnamon','1/2 cup chocolate chips','1/4 cup pistachios, chopped','1 orange, zested'], array['Drain the ricotta overnight in cheesecloth — wet filling ruins the shells.','Beat it smooth with the sugar, cinnamon and orange zest.','Fold in the chocolate chips.','Fill only at the moment of serving, and dip the ends in pistachios.'], 'Snack', 17408),
  ('03e45618-75a0-54bc-903e-e3edfe716156'::uuid, 'Affogato', array['4 scoops vanilla gelato','4 shots hot espresso','2 tbsp chopped hazelnuts'], array['Put the gelato in cold glasses.','Pull the espresso and pour it over at the table.','Hazelnuts on top. Eat before it collapses.'], 'Snack', 18432),
  ('aac4c79c-6cac-55e7-b97c-b70e09a1ad01'::uuid, 'Biscotti di Prato', array['2 cups all-purpose flour','1 cup granulated sugar','2 large eggs','1 tsp baking powder','1 cup almonds, whole','1 tsp vanilla extract','1 orange, zested','Pinch of salt'], array['Mix everything into a stiff dough with the almonds whole.','Shape into two logs and bake at 350°F for 25 minutes.','Cool 10 minutes, slice on the diagonal, then bake again 12 minutes a side.','They should be hard. They are meant to be dunked in Vin Santo.'], 'Snack', 19456),
  ('2187de6f-94ca-504c-8883-fd386f5e435d'::uuid, 'Focaccia', array['500g bread flour','400ml water','10g salt','5g active dry yeast','1/3 cup olive oil','2 fresh rosemary sprigs','Flaky salt to finish'], array['Mix a very wet dough and fold it four times over two hours.','Prove overnight in the fridge.','Pour a generous layer of oil into the tin and stretch the dough into it.','Dimple hard with your fingers, right to the bottom. Rosemary and flaky salt.','Bake at 450°F for 25 minutes until the base is crisp in the oil.'], 'Snack', 20480)
) as r(id, title, ing, steps, meal, pos)
on conflict (id) do update set title = excluded.title, ingredients = excluded.ingredients, steps = excluded.steps, meal = excluded.meal;
